entries[20667] = { ["name"] = "Corrosive Acid Breath", ["text"] = "Melee Range\nInstant\nShoots a cloud of acidic breath at enemies in a cone in front of the caster, reducing their armor and inflicting Nature damage every 5 sec. for 15 sec." }
entries[20668] = { ["name"] = "Sleepwalk", ["text"] = "30 yd range\nInstant\nTakes control of a humanoid enemy up to level 100 for 10 sec, increases the magical damage it deals by 300, and increases the Physical damage it deals by 100." }
entries[20669] = { ["name"] = "Sleep", ["text"] = "30 yd range\n1.3 sec cast\nPuts nearby enemies to sleep for up to 10 sec. Any damage caused will awaken them." }
entries[20671] = { ["name"] = "Summon Phantim Illusion", ["text"] = "Instant\nSummons a Phantim Illusion to fight for the caster for 10 sec." }
entries[20672] = { ["name"] = "Fade", ["text"] = "Instant\nTurns the caster invisible and increases its movement speed by 50% for 3 sec." }
