entries[20677] = { ["name"] = "Cleave", ["text"] = "15 yd range\nNext Melee\nInflicts Physical damage to an enemy and its nearest allies, affecting up to 3 targets." }
entries[20678] = { ["name"] = "Fireball", ["text"] = "250 Mana 50 yd range\n1 sec cast\nInflicts 11560 to 15640 Fire damage to an enemy." }
